// Client-side post search, generated by Parrot at build time. The index
// below is a trie of every published post's title, tag and category words;
// nothing is fetched at runtime. Restyle it through the .search* classes.
(() => {
  const INDEX = /*__PARROT_SEARCH_INDEX__*/null;
  const LIMIT = /*__PARROT_SEARCH_LIMIT__*/10;
  const POSTS_KEY = '$';

  // Same normalisation as Parrot::Search::SearchIndex.tokenize: lowercase, then runs
  // of letters, combining marks and digits.
  const tokenize = (text) => String(text || '').toLowerCase().match(/[\p{L}\p{M}\p{N}]+/gu) || [];

  // Every post id under the trie node `token` leads to, or null when no
  // indexed word starts with it. The trie is keyed by codepoint number, as
  // Ruby's each_codepoint built it.
  const idsWithPrefix = (token) => {
    let node = INDEX.trie;
    for (const char of token) {
      node = node[char.codePointAt(0)];
      if (!node) return null;
    }

    const ids = new Set();
    const stack = [node];
    while (stack.length) {
      const current = stack.pop();
      for (const [key, value] of Object.entries(current)) {
        if (key === POSTS_KEY) {
          value.forEach((id) => ids.add(id));
        } else {
          stack.push(value);
        }
      }
    }
    return ids;
  };

  // The posts ({ title, url }) matching every word of `query` as a prefix,
  // each once, newest first, at most LIMIT of them. [] for an empty query.
  const search = (query) => {
    const tokens = tokenize(query);
    if (!INDEX || tokens.length === 0) return [];

    let matches = null;
    for (const token of tokens) {
      const ids = idsWithPrefix(token);
      if (!ids) return [];
      matches = matches ? new Set([...matches].filter((id) => ids.has(id))) : ids;
    }

    return [...matches]
      .sort((a, b) => a - b)
      .slice(0, LIMIT)
      .map((id) => INDEX.posts[id]);
  };

  window.ParrotSearch = { search };

  // Wired-up inputs, mapped to the function that closes their suggestion
  // list. Keyed by element, so a body Turbo swaps in gets wired afresh
  // while one it morphs in place keeps its listeners.
  const closers = new WeakMap();

  const wire = (container) => {
    const input = container.querySelector('.search-input');
    const list = container.querySelector('.search-suggestions');
    if (!input || !list) return;

    let results = [];
    let active = -1;

    list.id ||= 'search-suggestions';
    input.setAttribute('role', 'combobox');
    input.setAttribute('aria-autocomplete', 'list');
    input.setAttribute('aria-controls', list.id);
    input.setAttribute('aria-expanded', 'false');

    const close = () => {
      list.hidden = true;
      list.innerHTML = '';
      results = [];
      active = -1;
      input.setAttribute('aria-expanded', 'false');
      input.removeAttribute('aria-activedescendant');
    };

    const highlight = (index) => {
      const items = list.querySelectorAll('.search-suggestion');
      active = index;
      items.forEach((item, i) => {
        const on = i === index;
        item.classList.toggle('is-active', on);
        item.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      if (index >= 0 && items[index]) {
        input.setAttribute('aria-activedescendant', items[index].id);
        items[index].scrollIntoView({ block: 'nearest' });
      } else {
        input.removeAttribute('aria-activedescendant');
      }
    };

    const render = () => {
      const query = input.value;
      if (tokenize(query).length === 0) return close();

      results = search(query);
      active = -1;
      list.innerHTML = '';

      if (results.length === 0) {
        const empty = document.createElement('li');
        empty.className = 'search-empty';
        empty.textContent = 'No matching posts';
        list.appendChild(empty);
      }

      results.forEach((post, index) => {
        const item = document.createElement('li');
        item.className = 'search-suggestion';
        item.id = `${list.id}-${index}`;
        item.setAttribute('role', 'option');
        item.setAttribute('aria-selected', 'false');
        const link = document.createElement('a');
        link.href = post.url;
        link.textContent = post.title;
        link.tabIndex = -1;
        item.appendChild(link);
        item.addEventListener('mousemove', () => { if (active !== index) highlight(index); });
        list.appendChild(item);
      });

      list.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      input.removeAttribute('aria-activedescendant');
    };

    input.addEventListener('input', render);
    input.addEventListener('focus', () => { if (input.value) render(); });

    input.addEventListener('keydown', (event) => {
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        if (results.length === 0) return;
        event.preventDefault();
        const step = event.key === 'ArrowDown' ? 1 : -1;
        highlight((active + step + results.length) % results.length);
      } else if (event.key === 'Enter') {
        const post = results[active >= 0 ? active : 0];
        if (!post) return;
        event.preventDefault();
        window.location.href = post.url;
      } else if (event.key === 'Escape') {
        input.value = '';
        close();
      }
    });

    closers.set(input, close);
  };

  const eachSearch = (callback) => {
    for (const container of document.querySelectorAll('.search')) {
      const input = container.querySelector('.search-input');
      callback(container, input, input && closers.get(input));
    }
  };

  // Wires up any search box not seen yet and shows every one. Runs on the
  // first load and again whenever Turbo puts a new or morphed page in place,
  // since the page's markup arrives hidden each time.
  const setup = () => {
    eachSearch((container, input) => {
      if (!input) return;
      if (!closers.has(input)) wire(container);
      if (closers.has(input)) container.hidden = false;
    });
  };

  document.addEventListener('click', (event) => {
    eachSearch((container, _input, close) => {
      if (close && !container.contains(event.target)) close();
    });
  });

  // Don't let Turbo cache a page with its suggestions open.
  document.addEventListener('turbo:before-cache', () => {
    eachSearch((_container, input, close) => {
      if (!close) return;
      input.value = '';
      close();
    });
  });

  ['turbo:load', 'turbo:render', 'turbo:morph', 'turbo:frame-load'].forEach((name) => {
    document.addEventListener(name, setup);
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setup);
  } else {
    setup();
  }
})();
